This code applies the merge "u + r -> ur". What does it print when it runs?

```
function birlestir(parcalar) {
  const sonuc = []
  for (let i = 0; i < parcalar.length; i++) {
    if (parcalar[i] === "u" && parcalar[i + 1] === "r") {
      sonuc.push("ur")
      i++
    } else {
      sonuc.push(parcalar[i])
    }
  }
  return sonuc
}
console.log(birlestir(["d","u","r","u","r"]).join(" "))
```

